import os
import time
import requests

ASSEMBLYAI_API_BASE_URL = "https://api.assemblyai.com/v2"

def batch_transcribe_meeting_with_diarization(audio_url: str, poll_interval: int = 5, max_attempts: int = 60) -> dict:
    api_key = os.environ.get("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise ValueError("ASSEMBLYAI_API_KEY environment variable must be set")

    headers = {
        "authorization": api_key,
        "content-type": "application/json"
    }

    submit_payload = {
        "audio_url": audio_url,
        "speaker_labels": True,
        "speech_model": "best"
    }

    submit_response = requests.post(
        f"{ASSEMBLYAI_API_BASE_URL}/transcript",
        json=submit_payload,
        headers=headers
    )
    submit_response.raise_for_status()
    transcript_id = submit_response.json()["id"]

    for _ in range(max_attempts):
        time.sleep(poll_interval)
        status_response = requests.get(
            f"{ASSEMBLYAI_API_BASE_URL}/transcript/{transcript_id}",
            headers=headers
        )
        status_response.raise_for_status()
        result = status_response.json()

        if result["status"] == "completed":
            return {
                "transcript_id": transcript_id,
                "audio_url": audio_url,
                "diarized_utterances": [
                    {
                        "speaker": ut["speaker"],
                        "text": ut["text"],
                        "start_time_ms": ut["start"],
                        "end_time_ms": ut["end"]
                    }
                    for ut in result.get("utterances", [])
                ]
            }
        elif result["status"] == "error":
            raise RuntimeError(f"Transcription failed: {result.get('error')}")

    raise TimeoutError(f"Transcription job {transcript_id} timed out after {max_attempts * poll_interval} seconds")
